from convert.adapters.solidworks.Container.Container import SldprtArchive
from convert.adapters.solidworks.Core.TypedResolved.Sweeps.Cold.ReadColdSw import (
    ReadColdSw,
)
from interchange.document.Behavior.DocumentIo import ToJson
from interchange.document.Models.DocumentModel import CadDocument


# receipts authorize generated bytes while complete source comparison protects every projected field
def CheckSwRead(DocumentValue: CadDocument, Payload: bytes) -> None:
    SourceName = DocumentValue.source.path
    Expected = ReadColdSw(
        SldprtArchive.from_bytes(Payload, SourceName),
        Payload,
        SourceName,
        DocumentValue.brep is not None,
    )
    if ToJson(DocumentValue, IndentSize=None) != ToJson(Expected, IndentSize=None):
        raise ValueError(
            "SOLIDWORKS cold sweep readback differs from its regenerated part"
        )
